CREATE OR REPLACE FUNCTION calculate_gross_total(subtotal NUMERIC, tax_rate NUMERIC)
RETURNS NUMERIC AS $$
    SELECT ROUND(subtotal * (1 + tax_rate), 2);
$$ LANGUAGE sql IMMUTABLE PARALLEL SAFE;

CREATE OR REPLACE FUNCTION order_month(ts timestamptz)
RETURNS date
LANGUAGE sql
IMMUTABLE
AS $$
    SELECT date_trunc('month', ts)::date;
$$;

CREATE INDEX idx_orders_month
ON orders (order_month(ordered_at));

SELECT count(*)
FROM orders
WHERE order_month(ordered_at) = DATE '2024-05-01';
